/* =========================================================
   MUYÃ‹ â€” RECLAIMED OBJECTS STUDIO
   DirecciÃ³n: editorial contemporÃ¡nea / artesanÃ­a premium
   TipografÃ­a original conservada: New Tegomin
   ========================================================= */

@font-face {
    font-family: "Numbskull";
    src: url("Numbskull.otf") format("opentype");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

:root {
    color-scheme: light;
    --paper: #f2efe6;
    --paper-deep: #e8e3d7;
    --ink: #20251d;
    --ink-soft: #55594e;
    --olive: #536342;
    --olive-dark: #35432d;
    --acid: #c5d17b;
    --clay: #bd684b;
    --line: rgba(32, 37, 29, .17);
    --white: #fffdf7;
    --font-heading: 'New Tegomin', serif;
    --font-body: 'New Tegomin', serif;
    --ease: cubic-bezier(.2, .75, .25, 1);
    --page-gutter: clamp(1.2rem, 6vw, 6.5rem);
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 1rem; }
body {
    margin: 0;
    background: var(--paper);
    color: var(--ink);
    font-family: var(--font-body);
    line-height: 1.6;
    overflow-x: clip;
}
body, button, a { font-family: var(--font-body); }
.numbskull-brand { font-family: "Numbskull", var(--font-body); }
a { color: inherit; text-decoration: none; }
button { color: inherit; }
img { display: block; max-width: 100%; }
::selection { color: var(--paper); background: var(--olive); }

/* Hero */
.hero {
    position: relative;
    isolation: isolate;
    min-height: min(760px, 100svh);
    display: flex;
    align-items: center;
    padding: 6rem var(--page-gutter) 7rem;
    overflow: hidden;
    background:
        radial-gradient(ellipse at 78% 32%, rgba(197, 209, 123, .23), transparent 35%),
        radial-gradient(ellipse at 8% 90%, rgba(189, 104, 75, .10), transparent 32%),
        var(--paper);
}
.hero::before {
    content: "M";
    position: absolute;
    z-index: -1;
    right: 5%;
    top: 48%;
    transform: translateY(-50%) rotate(-8deg);
    color: rgba(83, 99, 66, .055);
    font-size: clamp(24rem, 53vw, 58rem);
    line-height: .7;
    pointer-events: none;
}
.hero-orbit {
    position: absolute;
    z-index: 0;
    right: 10%;
    top: 13%;
    width: clamp(160px, 25vw, 340px);
    height: clamp(160px, 25vw, 340px);
    aspect-ratio: 1;
    display: grid;
    place-items: center;
    pointer-events: none;
}
.hero-orbit img {
    width: 86%;
    height: 86%;
    object-fit: contain;
}
.hero-content { position: relative; z-index: 1; width: min(850px, 78%); animation: hero-enter .9s var(--ease) both; }
.eyebrow {
    display: flex;
    align-items: center;
    gap: .65rem;
    margin: 0 0 1.5rem;
    color: var(--olive);
    font-family: var(--font-body);
    font-size: .7rem;
    font-weight: 700;
    letter-spacing: .18em;
    line-height: 1.5;
}
.eyebrow > span {
    display: inline-block;
    width: 7px; height: 7px;
    flex: 0 0 7px;
    border-radius: 50%;
    background: var(--clay);
    box-shadow: 0 0 0 4px rgba(189, 104, 75, .12);
}
.hero h1 {
    max-width: 900px;
    margin: 0;
    font-size: clamp(4rem, 9.6vw, 9.5rem);
    font-weight: 400;
    letter-spacing: -.075em;
    line-height: .98;
}
.hero h1 em, .about-container h2 em {
    color: var(--olive);
    font-weight: 400;
}
.hero-description {
    max-width: 430px;
    margin: 2rem 0 2.3rem;
    color: var(--ink-soft);
    font-size: clamp(1rem, 1.35vw, 1.18rem);
    line-height: 1.8;
}
.hero-actions { display: flex; align-items: center; gap: 1.5rem; flex-wrap: wrap; }
.button-primary {
    display: inline-flex;
    align-items: center;
    gap: 1.7rem;
    padding: 1rem 1.35rem;
    background: var(--olive-dark);
    color: var(--white);
    border: 1px solid var(--olive-dark);
    font-size: .85rem;
    transition: transform .3s var(--ease), background .3s ease, box-shadow .3s ease;
}
.button-primary i { transition: transform .3s var(--ease); }
.button-primary:hover {
    transform: translateY(-4px);
    background: var(--ink);
    box-shadow: 0 12px 30px rgba(32, 37, 29, .14);
}
.button-primary:hover i { transform: translateY(4px); }
.hero-note, .hero-side-note, .hero-bottom, .catalog-footnote, .about-index, .footer-caption {
    font-size: .62rem;
    letter-spacing: .16em;
    color: var(--ink-soft);
}
.hero-side-note {
    position: absolute;
    right: var(--page-gutter);
    top: 50%;
    writing-mode: vertical-rl;
    transform: translateY(-50%);
}
.hero-bottom {
    position: absolute;
    left: var(--page-gutter);
    right: var(--page-gutter);
    bottom: 1.7rem;
    display: flex;
    justify-content: space-between;
    padding-top: 1rem;
    border-top: 1px solid var(--line);
}
.hero-bottom span:last-child { text-align: right; }

/* Cinta editorial */
.manifesto-strip {
    display: flex;
    justify-content: space-around;
    align-items: center;
    gap: 1rem;
    min-height: 66px;
    padding: 1rem var(--page-gutter);
    background: var(--olive-dark);
    color: var(--paper);
    font-size: .65rem;
    letter-spacing: .16em;
    text-align: center;
}
.manifesto-mark { color: var(--acid); font-size: 1.15rem; }

/* CatÃ¡logo */
.products-section { padding: clamp(5rem, 9vw, 9rem) var(--page-gutter) 6rem; }
.section-heading {
    display: flex;
    justify-content: space-between;
    align-items: end;
    gap: 2rem;
    max-width: 1320px;
    margin: 0 auto 3.3rem;
}
.section-heading .eyebrow { margin-bottom: 1rem; }
.section-heading h2 {
    margin: 0;
    font-size: clamp(3.3rem, 7vw, 6.5rem);
    font-weight: 400;
    letter-spacing: -.07em;
    line-height: 1;
}
.heading-period { color: var(--clay); }
.section-intro {
    max-width: 300px;
    margin: 0 0 .35rem;
    color: var(--ink-soft);
    font-size: .95rem;
    line-height: 1.8;
}
.products-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: clamp(1.2rem, 3vw, 3rem);
    max-width: 1320px;
    margin: 0 auto;
}
.products-grid > * { min-width: 0; }
.product-card {
    position: relative;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    background: #e9e5da;
    border: 1px solid rgba(32, 37, 29, .10);
    animation: card-enter .7s var(--ease) both;
    transition: transform .4s var(--ease), box-shadow .4s var(--ease);
}
.product-card:nth-child(2n) { animation-delay: .12s; }
.product-card:hover {
    transform: translateY(-7px);
    box-shadow: 0 22px 45px rgba(32, 37, 29, .10);
}
.product-image {
    position: relative;
    width: 100%;
    aspect-ratio: 1 / 1.04;
    overflow: hidden;
    background: #dcd8cb;
}
.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform .8s var(--ease), filter .6s ease;
}
.product-card:hover .product-image img { transform: scale(1.045); }
.tag {
    position: absolute;
    top: 1rem; left: 1rem;
    padding: .45rem .8rem;
    background: var(--paper);
    color: var(--ink);
    font-size: .64rem;
    letter-spacing: .1em;
    text-transform: uppercase;
}
.product-info {
    display: grid;
    grid-template-columns: 1fr auto;
    gap: .35rem 1rem;
    padding: 1.25rem clamp(1rem, 2vw, 1.7rem) 1.5rem;
}
.product-info h3 {
    grid-column: 1;
    margin: 0;
    font-size: clamp(1.1rem, 1.8vw, 1.55rem);
    font-weight: 400;
    line-height: 1.35;
}
.product-info .price {
    grid-column: 2;
    grid-row: 1;
    margin: .15rem 0 0;
    color: var(--olive-dark);
    font-size: .9rem;
    white-space: nowrap;
}
.product-info .description {
    grid-column: 1 / -1;
    margin: .3rem 0 .8rem;
    color: var(--ink-soft);
    font-size: .82rem;
    line-height: 1.7;
}
.btn-ws {
    grid-column: 1 / -1;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding: .85rem 1rem;
    background: transparent;
    border: 1px solid rgba(32, 37, 29, .3);
    color: var(--ink);
    font-size: .78rem;
    transition: color .25s ease, background .25s ease, border-color .25s ease;
}
.btn-ws::after {
    content: "â†—";
    font-family: Arial, sans-serif;
    font-size: 1rem;
    transition: transform .25s ease;
}
.btn-ws:hover { background: var(--olive-dark); border-color: var(--olive-dark); color: white; }
.btn-ws:hover::after { transform: translate(3px, -3px); }
.btn-ws i { color: #477b4a; }
.btn-ws:hover i { color: #9fd7a0; }
.catalog-error, .catalog-empty {
    grid-column: 1 / -1;
    padding: 3rem 1rem;
    color: var(--ink-soft);
    text-align: center;
    border: 1px dashed var(--line);
}
.catalog-error { color: #a32121; }
.catalog-footnote {
    display: flex;
    justify-content: space-between;
    gap: 1rem;
    max-width: 1320px;
    margin: 2rem auto 0;
    padding-top: 1rem;
    border-top: 1px solid var(--line);
}

/* Manifiesto / acerca de */
.about-section {
    position: relative;
    isolation: isolate;
    overflow: hidden;
    padding: clamp(5rem, 10vw, 9rem) var(--page-gutter);
    background: var(--ink);
    color: var(--paper);
}
.about-section::before {
    content: "";
    position: absolute;
    z-index: -1;
    width: 550px;
    aspect-ratio: 1;
    right: -170px;
    top: 5%;
    border: 1px solid rgba(242, 239, 230, .13);
    border-radius: 50%;
    box-shadow: 0 0 0 35px rgba(242, 239, 230, .025), 0 0 0 70px rgba(242, 239, 230, .02);
}
.about-index { position: absolute; top: 2rem; left: var(--page-gutter); color: rgba(242, 239, 230, .5); }
.about-container { max-width: 900px; margin: 0 auto; text-align: center; }
.eyebrow-light { justify-content: center; color: var(--acid); }
.about-container h2 {
    margin: 0 auto;
    font-size: clamp(2.8rem, 6.5vw, 6rem);
    font-weight: 400;
    letter-spacing: -.06em;
    line-height: 1.08;
}
.about-container h2 em { color: var(--acid); }
.about-copy {
    max-width: 620px;
    margin: 2.4rem auto 2rem;
    color: rgba(242, 239, 230, .7);
    font-size: .95rem;
    line-height: 1.9;
}
.about-copy p { margin: 0 0 1.1rem; }
.about-copy .about-lead { color: var(--paper); font-size: 1.15rem; }
.button-outline {
    display: inline-flex;
    align-items: center;
    gap: .8rem;
    padding: .9rem 1.2rem;
    border: 1px solid rgba(242, 239, 230, .4);
    color: var(--paper);
    font-size: .8rem;
    transition: background .3s ease, color .3s ease, border-color .3s ease;
}
.button-outline:hover { background: var(--acid); border-color: var(--acid); color: var(--ink); }
.button-arrow { margin-left: .6rem; font-size: .7rem; }
.about-stamp {
    position: absolute;
    right: var(--page-gutter);
    bottom: 2rem;
    color: rgba(197, 209, 123, .5);
    font-size: .65rem;
    line-height: 1.2;
    letter-spacing: .2em;
    text-align: center;
}

/* Footer */
.site-footer {
    display: grid;
    grid-template-columns: 1fr 1fr;
    align-items: center;
    gap: 1rem 2rem;
    padding: 2rem var(--page-gutter);
    background: var(--paper-deep);
    color: var(--ink-soft);
    font-size: .72rem;
}
.site-footer p { margin: 0; }
.site-footer p:nth-of-type(2) { text-align: right; }
.footer-caption { grid-column: 2 / -1; text-align: right; font-size: .58rem; }

/* WhatsApp flotante */
.whatsapp-float {
    position: fixed;
    z-index: 1100;
    right: 1.5rem;
    bottom: 5rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: .65rem;
    min-height: 54px;
    padding: 0 .75rem;
    border: 1px solid rgba(255,255,255,.2);
    border-radius: 100px;
    background: #285b3d;
    color: white;
    box-shadow: 0 8px 28px rgba(25, 54, 36, .24);
    font-size: .78rem;
    transition: transform .3s var(--ease), background .3s ease, box-shadow .3s ease;
}
.whatsapp-float i { font-size: 1.25rem; }
.whatsapp-float:hover {
    transform: translateY(-4px);
    background: #1f4930;
    box-shadow: 0 12px 32px rgba(25, 54, 36, .32);
}

/* Microinteracciones */
@keyframes hero-enter {
    from { opacity: 0; transform: translateY(28px); }
    to { opacity: 1; transform: translateY(0); }
}
@keyframes card-enter {
    from { opacity: 0; transform: translateY(24px); }
    to { opacity: 1; transform: translateY(0); }
}
@keyframes orbit {
    to { transform: rotate(360deg); }
}

/* Accesibilidad */
:focus-visible { outline: 2px solid var(--clay); outline-offset: 4px; }
@media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
        scroll-behavior: auto !important;
        animation-duration: .01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: .01ms !important;
    }
}

/* Tablet */
@media (max-width: 900px) {
    :root { --page-gutter: clamp(1.2rem, 4vw, 3rem); }
    .hero { min-height: 650px; }
    .hero-content { width: 85%; }
    .hero::before { right: -10%; }
    .site-footer { grid-template-columns: 1fr 1fr; }
    .footer-caption { grid-column: 1 / -1; }
}

/* MÃ³vil */
@media (max-width: 680px) {
    .hero {
        min-height: 680px;
        min-height: min(760px, 100svh);
        align-items: center;
        padding: 5rem 1.35rem 6rem;
    }
    .hero::before { top: 54%; right: -22%; font-size: 29rem; }
    .hero-orbit {
        top: 25%;
        right: 10%;
        width: clamp(120px, 34vw, 135px);
        height: clamp(120px, 34vw, 135px);
    }
    .hero-content { width: 100%; }
    .hero .eyebrow { max-width: 250px; font-size: .58rem; }
    .hero h1 { width: 58%; font-size: clamp(2.6rem, 13vw, 3.2rem); }
    .hero-description { max-width: 330px; margin: 1.6rem 0 1.8rem; font-size: .95rem; }
    .hero-actions { align-items: flex-start; flex-direction: column; gap: 1rem; }
    .hero-side-note { display: none; }
    .hero-bottom { left: 1.35rem; right: 1.35rem; bottom: 1.2rem; font-size: .52rem; }

    .manifesto-strip { justify-content: center; gap: .7rem; min-height: 58px; padding-inline: .7rem; }
    .manifesto-strip span:not(.manifesto-mark) { font-size: .52rem; letter-spacing: .08em; }
    .manifesto-mark { font-size: .8rem; }

    .products-section { padding: 5rem 1.1rem 4rem; }
    .section-heading { display: block; margin-bottom: 2rem; }
    .section-heading h2 { font-size: clamp(3.3rem, 14vw, 5rem); }
    .section-intro { margin-top: 1rem; font-size: .85rem; }
    .products-grid { grid-template-columns: minmax(0, 1fr); gap: 1.25rem; }
    .product-image { aspect-ratio: 1 / 1.05; }
    .product-info { padding: 1.1rem; }
    .product-info h3 { font-size: 1.2rem; }
    .catalog-footnote { font-size: .5rem; }

    .about-section { padding: 6rem 1.35rem 5rem; }
    .about-index { top: 1.5rem; left: 1.35rem; font-size: .52rem; }
    .about-container h2 { font-size: clamp(2.8rem, 11vw, 4.5rem); }
    .about-copy { margin: 1.8rem auto; font-size: .87rem; }
    .about-copy .about-lead { font-size: 1rem; }
    .about-stamp { right: 1.2rem; bottom: 1rem; }

    .site-footer { grid-template-columns: 1fr; gap: .8rem; padding: 2rem 1.35rem 6rem; }
    .site-footer p:nth-of-type(2), .footer-caption { text-align: left; }
    .footer-caption { grid-column: auto; }
    .whatsapp-float { right: 1rem; bottom: 1.5rem; min-height: 50px; }
}
